import type { CiGuardianConfig } from '../../config/types.js';

export const GITLAB_PIPELINE_PATH = '.gitlab-ci.yml';

export function renderGitLabPipeline(config: CiGuardianConfig): string {
  const lines = [
    '# Generated by @agnotic/ci-guardian. Do not edit directly.',
    '# Run quality checks identically locally and in GitLab CI.',
    'stages:',
    '  - quality',
    '',
    'default:',
    '  image: node:20',
    '  cache:',
    '    key:',
    '      files:',
    '        - package-lock.json',
    '    paths:',
    '      - .npm/',
    '',
    'guardian-ci:',
    '  stage: quality',
    '  before_script:',
    '    - npm ci --cache .npm --prefer-offline',
    '  script:',
    '    - npx ci-guardian run',
    '  artifacts:',
    '    when: always',
    '    paths:',
    `      - ${config.report.path}`,
    '  rules:',
    '    - if: $CI_PIPELINE_SOURCE == "merge_request_event"',
    '    - if: $CI_COMMIT_BRANCH == $CI_DEFAULT_BRANCH',
    '',
  ];
  return lines.join('\n');
}
